def stamp(t):
 ms=round(t*1000);return f'{ms//3600000:02}:{ms//60000%60:02}:{ms//1000%60:02},{ms%1000:03}'
for v in items:
 (root/'captions'/(v['nombre']+'.txt')).write_text(v['caption']+'\n\n#ÍndigoPy #CDE\n')
 entries=[]
 for a,b,text,_ in v['cues']:
  lines=textwrap.wrap(text,42)
  if len(lines)>2:raise ValueError(text)
  entries.append((a,b,'\n'.join(lines)))
 (root/v['srt']).write_text('\n\n'.join(f'{i+1}\n{stamp(a)} --> {stamp(b)}\n{x}' for i,(a,b,x) in enumerate(entries))+'\n')
